// FindMultiCacheByIDS 根据IDS查询多条数据，并设置缓存
func (c *CourseAppointmentRepo) FindMultiCacheByIDS(ctx context.Context, IDS []string) ([]*yanxue_model.CourseAppointment, error) {
	resp := make([]*yanxue_model.CourseAppointment, 0)
	cacheKeys := make([]string, 0)
	keyToParam := make(map[string]string)
	for _, item := range IDS {
		cacheKey := c.cache.Key(CacheCourseAppointmentByIDPrefix, item)
		cacheKeys = append(cacheKeys, cacheKey)
		keyToParam[cacheKey] = item
	}
	cacheValue, err := c.cache.FetchBatch2(ctx, cacheKeys, func(miss []string) (map[string]string, error) {
		dbValue := make(map[string]string)
		params := make([]string, 0)
		for _, item := range miss {
			dbValue[item] = ""
			params = append(params, keyToParam[item])
		}
		dao := yanxue_dao.Use(c.db).CourseAppointment
		result, err := dao.WithContext(ctx).Where(dao.ID.In(params...)).Find()
		if err != nil {
			return nil, err
		}
		for _, item := range result {
			marshal, err := c.encoding.Marshal(item)
			if err != nil {
				return nil, err
			}
			dbValue[c.cache.Key(CacheCourseAppointmentByIDPrefix, item.ID)] = string(marshal)
		}
		return dbValue, nil
	}, c.cache.TTL())
	if err != nil {
		return nil, err
	}
	for _, cacheKey := range cacheKeys {
		if cacheValue[cacheKey] != "" {
			tmp := new(yanxue_model.CourseAppointment)
			err := c.encoding.Unmarshal([]byte(cacheValue[cacheKey]), tmp)
			if err != nil {
				return nil, err
			}
			resp = append(resp, tmp)
		}
	}
	return resp, nil
}

