// DeleteUniqueIndexCache 删除索引存在的缓存
func (c *CourseAppointmentRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.CourseAppointment) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, c.cache.Key(CacheCourseAppointmentByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[c.cache.Key(CacheCourseAppointmentByIDPrefix, item.ID)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseAppointmentByCourseIDDatePeriodPrefix, item.CourseID, item.Date, item.Period)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseAppointmentByOrderIDPrefix, item.OrderID)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseAppointmentByCourseIDDatePrefix, item.CourseID, item.Date)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseAppointmentByCourseIDPrefix, item.CourseID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := c.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
